<?php
require_once 'app_bootstrap.php';require_once 'security.php';require_once 'booking-workflow.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in to manage your booking.');
$id=filter_input(INPUT_GET,'booking_id',FILTER_VALIDATE_INT)?:0;$type=($_GET['type']??'')==='cancel'?'cancel':'amend';
try{$db=db_connect();ensure_app_schema($db);$booking=$db->execute_query('SELECT b.*,p.name package_name,p.duration_days FROM bookings b LEFT JOIN packages p ON p.id=b.package_id WHERE b.id=? AND b.user_email=?',[$id,$_SESSION['user_email']])->fetch_assoc();if(!$booking)throw new RuntimeException('Booking not found.');if($type==='amend'&&(!in_array($booking['status'],['confirmed','in_progress'],true)||$booking['payment_status']!=='paid'))throw new RuntimeException('Date-change requests are available only for paid active bookings.');if($type==='cancel'&&(!in_array($booking['status'],['confirmed','in_progress'],true)||$booking['payment_status']!=='paid'))throw new RuntimeException('Unpaid bookings can be deleted directly. Paid active bookings must use cancellation and refund request.');if(active_booking_request($db,$type==='amend'?'booking_amendments':'cancellation_requests',$id))throw new RuntimeException('An active request already exists for this booking.');$quote=$type==='cancel'?cancellation_quote($db,$booking):null;}catch(Throwable $error){redirect_with_message('my-bookings.php',$error->getMessage());}
$duration=max(1,(int)($booking['duration_days']??((new DateTimeImmutable($booking['from_date']))->diff(new DateTimeImmutable($booking['to_date']))->days+1)));
$deduction=0.0;$deductionPercent=0.0;$policyReason='';
if($type==='cancel'&&$quote){$deduction=max(0,(float)$quote['paid']-(float)$quote['refund']);$deductionPercent=max(0,100-(float)$quote['percentage']);$policyReason=((int)$quote['days']).' day'.((int)$quote['days']===1?'':'s').' before departure, so the "'.$quote['name'].'" policy applies.';}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $type==='amend'?'Request Date Change':'Request Cancellation';?> | Travel India</title><link rel="icon" href="img/favicon.jpg?v=1" type="image/jpeg"><link rel="stylesheet" href="css/portal.css?v=17"></head><body class="trips-body"><?php include 'header.php';?>
<main class="portal-page request-page"><header class="portal-heading"><div><span>Booking <?php echo e($booking['booking_reference']);?></span><h1><?php echo $type==='amend'?'Request a date change':'Request cancellation';?></h1><p><?php echo e($booking['package_name']?:$booking['destination']);?> · <?php echo e(date('d M Y',strtotime($booking['from_date'])));?> to <?php echo e(date('d M Y',strtotime($booking['to_date'])));?></p></div><a class="portal-button secondary" href="my-bookings.php#booking-<?php echo $id;?>">Back to My Trips</a></header>
<section class="request-panel"><form method="post" action="booking-request-submit.php" class="request-form"><?php echo csrf_input();?><input type="hidden" name="booking_id" value="<?php echo $id;?>"><input type="hidden" name="request_type" value="<?php echo $type;?>">
<?php if($type==='amend'):?><div class="request-notice"><i class="fa-solid fa-circle-info"></i><p>Your confirmed dates remain reserved until an administrator approves this request. Availability and pricing will be checked again.</p></div><div class="form-pair"><label>Requested start date<input id="requested-from" type="date" name="requested_from_date" min="<?php echo date('Y-m-d');?>" required></label><label>Requested end date<input id="requested-to" type="date" name="requested_to_date" readonly required></label></div><input type="hidden" id="request-duration" value="<?php echo $duration;?>">
<?php else:?><div class="cancellation-quote"><span><b>Amount paid</b><?php echo inr($quote['paid']);?></span><span><b>Policy</b><?php echo e($quote['name']);?><small><?php echo e($policyReason);?></small></span><span><b>Deduction</b><?php echo number_format($deductionPercent,2);?>% · <?php echo inr($deduction);?></span><span><b>Estimated refund</b><?php echo inr($quote['refund']);?></span></div><div class="request-notice warning"><i class="fa-solid fa-triangle-exclamation"></i><p>This is an estimate. Ticket, hotel, payment, or other non-refundable charges may affect the final amount after review.</p></div><?php endif;?>
<label>Reason<textarea name="reason" maxlength="1000" required placeholder="Explain your request"></textarea></label><?php if($type==='cancel'):?><label class="policy-accept"><input type="checkbox" name="accept_policy" value="1" required><span>I have reviewed the estimated refund and understand that the administrator will confirm the final amount.</span></label><?php endif;?><button class="portal-button" type="submit"><i class="fa-solid fa-paper-plane"></i> Submit request</button></form></section></main><?php if($type==='cancel'):?><div class="request-confirm-modal" id="request-confirm-modal" hidden><div class="request-confirm-backdrop" data-close-request-confirm></div><section class="request-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="request-confirm-title"><button class="request-confirm-close" type="button" data-close-request-confirm aria-label="Close confirmation"><i class="fa-solid fa-xmark"></i></button><span>Refund estimate</span><h2 id="request-confirm-title">Confirm cancellation request</h2><p>Your request will be sent to the administrator for final review.</p><div class="request-confirm-summary"><div><span><strong>Amount paid</strong><small>Paid invoice amount for this booking</small></span><b><?php echo inr($quote['paid']);?></b></div><div><span><strong>Policy selected</strong><small><?php echo e($policyReason);?></small></span><b><?php echo e($quote['name']);?></b></div><div><span><strong>Refund percentage</strong><small>Policy allows this part of the paid amount to be refunded</small></span><b><?php echo number_format((float)$quote['percentage'],2);?>%</b></div><div class="deduction"><span><strong>Deduction</strong><small><?php echo number_format($deductionPercent,2);?>% policy deduction<?php echo (float)$quote['fee']>0?' plus '.inr($quote['fee']).' administrative fee':'';?></small></span><b>-<?php echo inr($deduction);?></b></div><div class="total"><span>Estimated refund</span><strong><?php echo inr($quote['refund']);?></strong></div></div><div class="request-notice warning"><i class="fa-solid fa-triangle-exclamation"></i><p>Final refund may change after admin verifies ticket, hotel, payment gateway, or other non-refundable charges.</p></div><div class="request-confirm-actions"><button type="button" class="portal-button secondary" data-close-request-confirm>Back to edit</button><button type="button" class="portal-button" id="confirm-request-submit"><i class="fa-solid fa-circle-check"></i> Send cancellation request</button></div></section></div><?php endif;?><?php include 'footer.php';?>
<?php if($type==='amend'):?><script>const start=document.querySelector('#requested-from'),end=document.querySelector('#requested-to'),duration=Number(document.querySelector('#request-duration').value);start.addEventListener('change',()=>{if(!start.value){end.value='';return}const date=new Date(start.value+'T00:00:00');date.setDate(date.getDate()+duration-1);end.value=[date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')});</script><?php else:?><script>const requestForm=document.querySelector('.request-form'),requestModal=document.querySelector('#request-confirm-modal'),confirmButton=document.querySelector('#confirm-request-submit');let requestConfirmed=false;const closeRequestModal=()=>{requestModal.hidden=true;document.body.classList.remove('request-modal-open')};document.querySelectorAll('[data-close-request-confirm]').forEach(button=>button.addEventListener('click',closeRequestModal));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!requestModal.hidden)closeRequestModal()});requestForm.addEventListener('submit',event=>{if(requestConfirmed)return;event.preventDefault();if(!requestForm.reportValidity())return;requestModal.hidden=false;document.body.classList.add('request-modal-open');confirmButton.focus()});confirmButton.addEventListener('click',()=>{requestConfirmed=true;closeRequestModal();requestForm.requestSubmit()});</script><?php endif;?></body></html>
